<?php
declare(strict_types=1); require_once __DIR__.'/_shared.php'; require_login();
$secretKeys=['openai_api_key','pexels_api_key','pixabay_api_key','instagram_client_secret','instagram_access_token'];
$fields=['openai_api_key'=>'OpenAI API key','openai_model'=>'OpenAI model','pexels_api_key'=>'Pexels API key','pixabay_api_key'=>'Pixabay API key','instagram_client_id'=>'Instagram app/client ID','instagram_client_secret'=>'Instagram app/client secret','instagram_business_account_id'=>'Instagram business account/page ID','instagram_access_token'=>'Instagram access token','default_hashtags'=>'Default hashtags','default_cta'=>'Default CTA','posting_timezone'=>'Posting timezone','daily_draft_limit'=>'Daily draft limit','auto_render'=>'Auto-render','auto_publish'=>'Auto-publish'];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); foreach($fields as $k=>$label){ $v=(string)($_POST[$k]??''); if(in_array($k,$secretKeys,true) && $v==='') continue; set_setting($k,$v,in_array($k,$secretKeys,true)); } if(($_POST['auto_publish']??'0')==='1') app_log('warning','Auto-publish enabled by admin'); flash('Settings saved. Secrets are masked and encrypted at rest where supported.'); redirect('settings.php'); }
$meta=all_settings_meta(); layout_header('Settings'); show_flash(); ?><div class="notice">Auto-publish is intentionally default OFF. Meta long-lived token refresh is not automatic; add a scheduled refresh flow before relying on unattended publishing.</div><form method="post" class="panel"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><?php foreach($fields as $k=>$label): $isSecret=in_array($k,$secretKeys,true); $val=get_setting($k); ?><label><?=h($label)?><?php if($isSecret): ?><input type="password" name="<?=h($k)?>" placeholder="<?=h(mask_secret($val))?>"><span class="small muted">Leave blank to keep existing value.</span><?php elseif($k==='auto_render'||$k==='auto_publish'): ?><select name="<?=h($k)?>"><option value="0" <?=$val!=='1'?'selected':''?>>Off</option><option value="1" <?=$val==='1'?'selected':''?>>On</option></select><?php else: ?><input name="<?=h($k)?>" value="<?=h($val)?>"><?php endif; ?></label><?php endforeach; ?></div><button>Save settings</button></form><?php layout_footer();
